hero_grid_json_feed.funcao_sniper_imagem:
const getHighResImage = (post, width, height) => {
    let imgUrl = 'https://placehold.co/' + width + 'x' + height + '/1e1e1e/FFF?text=News';
    if (post.media$thumbnail) {
        imgUrl = post.media$thumbnail.url;
    } else if (post.content && post.content.$t.match(/<img.+?src="([^"]+)"/)) {
        imgUrl = post.content.$t.match(/<img.+?src="([^"]+)"/)[1];
    }
    imgUrl = imgUrl.replace(/\/(s|w|h)\d+.*?(\/)/g, `/w${width}-h${height}-c$2`);
    imgUrl = imgUrl.replace(/=(s|w|h)\d+.*$/g, `=w${width}-h${height}-c`);
    return imgUrl;
};

