cyber_slider_widget.js_global_functions:
window.moveCyberSlide = function(direcao) {
    const slides = document.querySelectorAll('#cyber-slider-track .cyber-slide');
    if(slides.length === 0) return;
    slides[cyberSlideIndex].classList.remove('active-slide');
    cyberSlideIndex += direcao;
    if (cyberSlideIndex >= slides.length) cyberSlideIndex = 0;
    if (cyberSlideIndex < 0) cyberSlideIndex = slides.length - 1;
    slides[cyberSlideIndex].classList.add('active-slide');
    window.resetCyberRotacao();
};
window.iniciarCyberRotacao = function() {
    cyberSlideInterval = setInterval(() => window.moveCyberSlide(1), 5000);
};
window.resetCyberRotacao = function() {
    clearInterval(cyberSlideInterval);
    window.iniciarCyberRotacao();
};

posts_relacionados.javascript:
document.addEventListener('DOMContentLoaded', () => {
    const relatedContainer = document.getElementById('vm-related-posts');
    if (!relatedContainer) return;
    const currentUrl = window.location.href.split('?')[0];
    const label = relatedContainer.getAttribute('data-label');
    if (!label) { relatedContainer.innerHTML = ''; return; }
    const feedUrl = `/feeds/posts/default/-/${encodeURIComponent(label)}?alt=json&max-results=4`;
    fetch(feedUrl).then(r => r.json()).then(data => {
        const posts = data.feed.entry || [];
        let html = '';
        let count = 0;
        posts.forEach(post => {
            let link = post.link.find(l => l.rel === 'alternate').href;
            if (link.split('?')[0] === currentUrl || count >= 3) return;
            let title = post.title.$t;
            let img = post.media$thumbnail
                ? post.media$thumbnail.url.replace(/\/(s|w|h)\d+.*?(\/)/g, '/w400-h250-c$2').replace(/=(s|w|h)\d+.*$/g, '=w400-h250-c')
                : 'https://placehold.co/400x250/1e1e1e/FFF?text=News';
            html += `<div class="col-md-4">
                        <article class="mag-card h-100 shadow-sm border-0">
                            <a href="${link}" class="d-block" style="height:160px; overflow:hidden; border-radius:8px 8px 0 0">
                                <img src="${img}" class="w-100 h-100 mag-img" style="object-fit:cover" alt="${title}" loading="lazy">
                            </a>
                            <div class="p-3 bg-body border border-top-0" style="border-radius:0 0 8px 8px">
                                <h3 class="h6 fw-bold mb-0" style="display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; line-height:1.4">
                                    <a href="${link}" class="text-body text-decoration-none">${title}</a>
                                </h3>
                            </div>
                        </article>
                    </div>`;
            count++;
        });
        relatedContainer.innerHTML = count === 0 ? '<div class="col-12 text-muted small">Nenhuma postagem relacionada.</div>' : html;
    }).catch(() => { relatedContainer.innerHTML = ''; });
});

