tempo_de_leitura.javascript:
document.addEventListener('DOMContentLoaded', function() {
    const postBody = document.querySelector('.post-body');
    if (!postBody) return;
    if (document.getElementById('vm-reading-time')) return;
    const textContent = postBody.innerText || postBody.textContent;
    const wordCount = textContent.trim().split(/\s+/).length;
    const readingTime = Math.ceil(wordCount / 200);
    if (readingTime < 1) return;
    const timeBadge = document.createElement('div');
    timeBadge.id = 'vm-reading-time';
    const minText = readingTime === 1 ? 'minuto' : 'minutos';
    timeBadge.innerHTML = `<i class="bi bi-clock-history"></i> Leitura de ${readingTime} ${minText}`;
    postBody.insertBefore(timeBadge, postBody.firstChild);
});

